USE sql_notes;
SELECT s.name, d.dept_name FROM students s JOIN departments d ON s.dept_id=d.dept_id;
SELECT s.name, c.course_name FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN courses c ON e.course_id=c.course_id ORDER BY s.name;
SELECT s.name, e.course_id FROM students s LEFT JOIN enrollments e ON s.student_id=e.student_id;
SELECT c.course_name, e.student_id FROM courses c LEFT JOIN enrollments e ON c.course_id=e.course_id ORDER BY c.course_id;
SELECT s.name FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN courses c ON e.course_id=c.course_id WHERE c.course_name='Database Management';
SELECT COUNT(*) AS combos FROM students CROSS JOIN departments;
SELECT a.name AS s1, b.name AS s2 FROM students a JOIN students b ON a.dept_id=b.dept_id AND a.student_id<b.student_id;
SELECT s.name FROM students s LEFT JOIN enrollments e ON s.student_id=e.student_id WHERE e.enrollment_id IS NULL;
SELECT c.course_name FROM courses c LEFT JOIN enrollments e ON c.course_id=e.course_id WHERE e.enrollment_id IS NULL;
SELECT c.course_name, COUNT(e.enrollment_id) AS n FROM courses c LEFT JOIN enrollments e ON c.course_id=e.course_id GROUP BY c.course_id,c.course_name;
SELECT s.name, ROUND(AVG(m.marks_obtained),2) AS avg_m FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN marks m ON m.enrollment_id=e.enrollment_id GROUP BY s.student_id,s.name;
SELECT s.name,c.course_name,m.marks_obtained,m.grade FROM students s JOIN enrollments e ON s.student_id=e.student_id JOIN courses c ON e.course_id=c.course_id JOIN marks m ON m.enrollment_id=e.enrollment_id ORDER BY m.marks_obtained DESC;
SELECT d.dept_name,s.name FROM departments d LEFT JOIN students s ON d.dept_id=s.dept_id UNION SELECT d.dept_name,s.name FROM departments d RIGHT JOIN students s ON d.dept_id=s.dept_id;
SELECT s.name,c.course_name FROM students s JOIN enrollments e ON s.student_id=e.student_id AND e.semester=3 JOIN courses c ON e.course_id=c.course_id WHERE c.course_name='Database Management';
SELECT c.course_name,s.name,m.marks_obtained FROM marks m JOIN enrollments e ON m.enrollment_id=e.enrollment_id JOIN students s ON e.student_id=s.student_id JOIN courses c ON e.course_id=c.course_id WHERE (e.course_id,m.marks_obtained) IN (SELECT e2.course_id,MAX(m2.marks_obtained) FROM enrollments e2 JOIN marks m2 ON m2.enrollment_id=e2.enrollment_id GROUP BY e2.course_id);
SELECT s.name,COUNT(*) AS c FROM students s JOIN enrollments e ON s.student_id=e.student_id GROUP BY s.student_id,s.name HAVING COUNT(*)>1;
SELECT COUNT(*) AS joined_rows, COUNT(DISTINCT s.student_id) AS unique_students FROM students s JOIN enrollments e ON s.student_id=e.student_id;
SELECT s.name,c.course_name FROM students s CROSS JOIN courses c LEFT JOIN enrollments e ON e.student_id=s.student_id AND e.course_id=c.course_id WHERE e.enrollment_id IS NULL;
SELECT d.dept_name,COUNT(DISTINCT s.student_id) AS studs,COUNT(DISTINCT c.course_id) AS crs FROM departments d LEFT JOIN students s ON d.dept_id=s.dept_id LEFT JOIN courses c ON c.dept_id=d.dept_id GROUP BY d.dept_id,d.dept_name;
SELECT s.name,c.course_name,a.percentage,m.marks_obtained FROM students s JOIN attendance a ON a.student_id=s.student_id JOIN courses c ON c.course_id=a.course_id JOIN enrollments e ON e.student_id=s.student_id AND e.course_id=c.course_id JOIN marks m ON m.enrollment_id=e.enrollment_id WHERE a.percentage>=90 AND m.marks_obtained>=85;
